const pointerLeave = fireEvent.pointerLeave
fireEvent.pointerEnter = (...args) => {
  pointerEnter(...args)
  return fireEvent.pointerOver(...args)
}
fireEvent.pointerLeave = (...args) => {
  pointerLeave(...args)
  return fireEvent.pointerOut(...args)
